// GENERATED by crates/romacs-vm/tools/varh/varh.py (`varh.py rust`) from
// tools/varh/replay.rs.in; live GNU is not needed to run this test.
//
// Variable semantics are global state: every case runs in a FRESH Vm
// (collection floor 1), mirroring the fresh `emacs -Q --batch` process per case
// per regime that recorded the evidence.  Expected outcomes are GNU's;
// divergences must be pinned with their class (NEW DIVERGENCE / STALE PIN /
// CHANGED PIN / UNKNOWN PIN all fail).
use romacs_vm::Vm;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

const EVIDENCE: &str = include_str!("../tools/varh/evidence/varh.json");
const CASES: &str = include_str!("../tools/varh/cases.json");
const WRAP: (&str, &str) = ("(prin1-to-string (condition-case e (list 'ok ", ") (error (list 'sig e))))");

fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

fn classify(expected: &str, actual: &str) -> &'static str {
    if expected == actual { return "PASS"; }
    if actual.starts_with("VM-ERROR") {
        return if actual.contains("print") { "PRINTER" } else { "VM-INTERNAL" };
    }
    if actual.starts_with("(sig (void-function") { return "MISSING"; }
    let e_sig = expected.starts_with("(sig ");
    let a_sig = actual.starts_with("(sig ");
    if e_sig && a_sig {
        let condition = |s: &str| s[6..].split(' ').next().unwrap().trim_end_matches(')').to_owned();
        return if condition(expected) == condition(actual) { "DATA" } else { "CONDITION" };
    }
    if e_sig != a_sig { return "SIGNAL-VS-VALUE"; }
    if expected.contains("#<") || expected.contains("#[") || actual.contains("#<") { return "PRINTER"; }
    "VALUE"
}

/// The evidence must have been recorded from exactly these inputs.
fn validate(ev: &Value) {
    assert_eq!(ev["protocol"], "varh-v1", "evidence protocol changed; re-record");
    assert_eq!(ev["cases_sha256"], hash(CASES.as_bytes()), "cases.json changed; re-record");
    assert_eq!(ev["harness_sha256"], hash(include_bytes!("../tools/varh/varh.py")), "varh.py changed; re-record");
    assert_eq!(ev["driver_sha256"], hash(include_bytes!("../tools/varh/gnu_driver.el")), "gnu_driver.el changed; re-record");
    assert_eq!(ev["replay_sha256"], hash(include_bytes!("../tools/varh/replay.rs.in")), "replay.rs.in changed; re-record");
    let cases: Value = serde_json::from_str(CASES).unwrap();
    let cases = cases.as_array().unwrap();
    let rows = ev["cases"].as_array().unwrap();
    assert_eq!(cases.len(), rows.len(), "recorded case count differs from cases.json");
    for (case, row) in cases.iter().zip(rows) {
        for key in ["id", "family", "kind", "variable", "form"] {
            assert_eq!(case[key], row[key], "recorded case differs from cases.json at {key}");
        }
        assert_eq!(case.get("setup").unwrap_or(&Value::Null), &row["setup"], "recorded setup differs");
        let source = format!("{}{}{}", WRAP.0, case["form"].as_str().unwrap(), WRAP.1);
        assert_eq!(row["source"].as_str().unwrap(), source, "recorded source is not the wrapped form");
    }
}

fn run(row: &Value) -> String {
    let mut vm = Vm::new();
    vm.set_collection_floor(1);
    if let Some(setup) = row["setup"].as_str() {
        if let Err(e) = vm.eval_source(setup) {
            return format!("VM-ERROR setup {e}");
        }
    }
    match vm.eval_source(row["source"].as_str().unwrap()) {
        Ok(v) => v.display().map(|s| serde_json::from_str::<String>(&s).unwrap_or(s)).unwrap_or_else(|e| format!("VM-ERROR {e}")),
        Err(e) => format!("VM-ERROR {e}"),
    }
}

fn replay(ev: &Value) -> std::collections::BTreeMap<String, usize> {
    let mut counts = std::collections::BTreeMap::new();
    let pinned = ev["pinned"].as_object().cloned().unwrap_or_default();
    let rows = ev["cases"].as_array().unwrap();
    let ids: BTreeSet<_> = rows.iter().map(|r| r["id"].as_str().unwrap()).collect();
    assert_eq!(ids.len(), rows.len(), "duplicate case IDs");
    let mut bad = Vec::new();
    for key in pinned.keys() {
        if !ids.contains(key.as_str()) { bad.push(format!("UNKNOWN PIN: {key}")); }
    }
    for row in rows {
        let id = row["id"].as_str().unwrap();
        let pin = pinned.get(id);
        let actual = run(row);
        let expected = row["expected"].as_str().unwrap();
        let same = actual == expected || row["gnu_regime_variant"].as_str() == Some(actual.as_str());
        let verdict = if actual == expected { "PASS" } else if same { "PASS-REGIME" } else { classify(expected, &actual) };
        *counts.entry(verdict.to_owned()).or_insert(0) += 1;
        let form = row["form"].as_str().unwrap();
        match (same, pin) {
            (true, Some(c)) => bad.push(format!("STALE PIN ({c}): {id}: {form}")),
            (false, None) => bad.push(format!("NEW DIVERGENCE ({}): {id}: {form}\n  GNU {expected}\n  VM2 {actual}", classify(expected, &actual))),
            (false, Some(c)) if c.as_str() != Some(classify(expected, &actual)) =>
                bad.push(format!("CHANGED PIN ({c} -> {}): {id}: {form}\n  GNU {expected}\n  VM2 {actual}", classify(expected, &actual))),
            _ => {}
        }
    }
    println!("varh Rust replay (fresh Vm per case, collection floor 1): {} cases {:?}", rows.len(), counts);
    assert!(bad.is_empty(), "{} varh ratchet violations:\n{}", bad.len(), bad.join("\n"));
    counts
}

fn evidence() -> Value {
    serde_json::from_str(EVIDENCE).unwrap()
}

#[test]
fn varh_fresh_vm_replay() {
    let ev = evidence();
    validate(&ev);
    let counts = replay(&ev);
    assert_eq!(counts.values().sum::<usize>(), ev["cases"].as_array().unwrap().len());
}

// Harness self-tests: a real live-GNU row (boundp of a built-in) run through
// the real VM, then mutated.  None invents an expected outcome.
fn smoke() -> Value {
    let mut ev = evidence();
    let row = ev["cases"].as_array().unwrap().iter()
        .find(|r| r["form"] == "(boundp 'undo-limit)" && r["expected"] == "(ok t)")
        .expect("live GNU row (boundp 'undo-limit)").clone();
    ev["cases"] = serde_json::json!([row]);
    ev["pinned"] = serde_json::json!({});
    ev
}

#[test]
fn varh_harness_smoke() {
    let counts = replay(&smoke());
    assert_eq!(counts.get("PASS"), Some(&1), "smoke row must pass");
}

#[test]
#[should_panic(expected = "NEW DIVERGENCE")]
fn varh_harness_new_divergence_mutation() {
    let mut ev = smoke();
    ev["cases"][0]["source"] = serde_json::json!("(prin1-to-string (list 'ok nil))");
    replay(&ev);
}

#[test]
#[should_panic(expected = "STALE PIN")]
fn varh_harness_stale_pin_mutation() {
    let mut ev = smoke();
    let id = ev["cases"][0]["id"].as_str().unwrap().to_owned();
    ev["pinned"][id] = serde_json::json!("VALUE");
    replay(&ev);
}

#[test]
#[should_panic(expected = "CHANGED PIN")]
fn varh_harness_changed_pin_mutation() {
    let mut ev = smoke();
    ev["cases"][0]["source"] = serde_json::json!("(prin1-to-string (list 'ok nil))");
    let id = ev["cases"][0]["id"].as_str().unwrap().to_owned();
    ev["pinned"][id] = serde_json::json!("CONDITION");
    replay(&ev);
}

#[test]
#[should_panic(expected = "UNKNOWN PIN")]
fn varh_harness_unknown_pin_mutation() {
    let mut ev = smoke();
    ev["pinned"]["no-such-case/000"] = serde_json::json!("VALUE");
    replay(&ev);
}

#[test]
#[should_panic(expected = "cases.json changed")]
fn varh_harness_stale_evidence_mutation() {
    let mut ev = evidence();
    ev["cases_sha256"] = serde_json::json!("0");
    validate(&ev);
}
